215	import com.evento.common.modeling.annotations.component.Aggregate;
216	import com.evento.common.modeling.annotations.handler.AggregateCommandHandler;
217	import com.evento.common.modeling.annotations.handler.EventSourcingHandler;
218	import com.study.app.domain.command.CreateOrderCommand;
219	import com.study.app.domain.event.OrderCreatedEvent;
