221	@Aggregate(snapshotFrequency = 5)
222	public class OrderAggregate {
223	
224	    // init=true => creation handler; state is null until the first event is applied.
225	    @AggregateCommandHandler(init = true)
226	    OrderCreatedEvent handle(CreateOrderCommand cmd, OrderAggregateState state) {
227	        if (cmd.getOrderId() == null || cmd.getOrderId().isBlank()) {
228	            throw new IllegalArgumentException("orderId is required"); // rejects the command
229	        }
230	        return new OrderCreatedEvent(cmd.getOrderId(), cmd.getDescription(), cmd.getQuantity());
231	    }
232	
233	    // Returns the (possibly newly created) state; the framework persists it for replay.
234	    @EventSourcingHandler
235	    OrderAggregateState on(OrderCreatedEvent e, OrderAggregateState state) {
236	        if (state == null) state = new OrderAggregateState();
237	        state.setDescription(e.getDescription());
238	        state.setQuantity(e.getQuantity());
239	        state.setStatus("CREATED");
240	        return state;
241	    }
242	}
