            log.warn("command {} failed: {}", cmd.getClass().getSimpleName(), rootMessage(ex));
        }
    }

    private static String rootMessage(Throwable t) {
        Throwable c = t;
        while (c.getCause() != null && c.getCause() != c) c = c.getCause();
        return c.getMessage();
    }

